def get_script_fingerprint(file_path=None):
    """计算当前脚本内容的 SHA-256 指纹，用于检测用户是否替换了新版脚本并自动覆盖旧版自动化任务"""
    target = file_path or os.path.abspath(__file__)
    try:
        with open(target, "rb") as f:
            return hashlib.sha256(f.read()).hexdigest()[:16]
    except Exception:
        return "v11_0_34"


